"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12938"],{7614(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.tipo_processo_codigo_tamanho","status":422,"titulo":"C\xf3digo do tipo de processo excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.tipo_processo_codigo_tamanho","requisitos":[],"oQueAconteceu":["O `tipoProcessoCodigo` enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) tem mais de 64 caracteres, depois de aparados os espa\xe7os nas pontas. \xc9 o mesmo limite do c\xf3digo do tipo de processo no cadastro de tipos.","A recusa vem na lista `errors` da resposta, com `field` igual a `tipoProcessoCodigo`. Um c\xf3digo desse tamanho n\xe3o existe no cadastro de tipos de processo, ent\xe3o a resposta traz tamb\xe9m [tipo de processo inexistente](/erros/uniplus.configuracao.modelo_formulario.tipo_processo_inexistente), e essa recusa vem antes na lista: o `code` da raiz da resposta \xe9 o da primeira recusa, e esta fica em `errors`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Use o c\xf3digo de um tipo de processo cadastrado, que tem at\xe9 64 caracteres. Consulte os tipos em `GET /api/configuracao/tipos-processo`."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);